class Solution {
    public boolean reorderedPowerOf2(int n){
        String target=signature(n);
        for(int power=1;power>0&&power<=1000000000;power<<=1)if(signature(power).equals(target))return true;
        return false;
    }
    private String signature(int value){
        char[] chars=Integer.toString(value).toCharArray();
        Arrays.sort(chars);
        return new String(chars);
    }
}

code.kotlin:
class Solution {
    fun reorderedPowerOf2(n:Int):Boolean{
        val target=signature(n);
        var power=1;
        while(power>0&&power<=1000000000){
            if(signature(power)==target)return true;
            power=power shl 1
        };
        return false
    };
    private fun signature(value:Int)=value.toString().toCharArray().sorted().joinToString("")
}

